{{
(() => {
  const token = String(
    appsmith.store.savveyra_access_token || ""
  );

  let issuedAt = null;
  let expiresAt = null;
  let tokenError = null;

  try {
    if (token) {
      const payload = JSON.parse(
        atob(
          token.split(".")[1]
            .replace(/-/g, "+")
            .replace(/_/g, "/")
        )
      );

      issuedAt = payload.iat
        ? new Date(payload.iat * 1000).toISOString()
        : null;

      expiresAt = payload.exp
        ? new Date(payload.exp * 1000).toISOString()
        : null;
    }
  } catch (error) {
    tokenError = String(error.message);
  }

  const now = Date.now();

  return JSON.stringify({
    currentTime: new Date(now).toISOString(),
    accessTokenPresent: !!token,
    refreshTokenPresent:
      !!appsmith.store.savveyra_refresh_token,
    tokenIssuedAt: issuedAt,
    tokenExpiresAt: expiresAt,
    tokenExpired: expiresAt
      ? now >= Date.parse(expiresAt)
      : null,
    minutesUntilExpiry: expiresAt
      ? Math.round((Date.parse(expiresAt) - now) / 60000)
      : null,
    sessionRelatedStoreKeys: Object.keys(
      appsmith.store
    ).filter(key =>
      /token|expir|login|session|auth/i.test(key)
    ),
    tokenError: tokenError
  }, null, 2);
})()
}}
